def solve_transformation(grid):
    """Apply color-swap based on rectangular outline topology"""
    rows = len(grid)
    cols = len(grid[0])
    bg = 6  # Background color

    visited = [[False]*cols for _ in range(rows)]
    all_comps = {}

    def find_component(start_r, start_c, color):
        pixels = []
        stack = [(start_r, start_c)]
        local_visited = set()

        while stack:
            r, c = stack.pop()
            if (r, c) not in local_visited and grid[r][c] == color:
                local_visited.add((r, c))
                pixels.append((r, c))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in local_visited and grid[nr][nc] == color:
                        stack.append((nr, nc))

        min_r, max_r = min(p[0] for p in pixels), max(p[0] for p in pixels)
        min_c, max_c = min(p[1] for p in pixels), max(p[1] for p in pixels)

        top_pixels = [grid[min_r][c] for c in range(min_c, max_c+1)]
        bot_pixels = [grid[max_r][c] for c in range(min_c, max_c+1)]
        left_pixels = [grid[r][min_c] for r in range(min_r, max_r+1)]
        right_pixels = [grid[r][max_c] for r in range(min_r, max_r+1)]

        return {
            'pixels': set(pixels),
            'color': color,
            'bbox': (min_r, max_r, min_c, max_c),
            'pixel_count': len(pixels),
            'top_solid': all(p == color for p in top_pixels),
            'bot_solid': all(p == color for p in bot_pixels),
            'left_solid': all(p == color for p in left_pixels),
            'right_solid': all(p == color for p in right_pixels),
        }

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and not visited[r][c]:
                comp = find_component(r, c, grid[r][c])
                visited[r][c] = True
